#!/usr/bin/env node
/**
 * Kura code rules, generated by the kura-rules-setup skill. Language-neutral: it reads source text (any language) and
 * takes function complexity from lizard (C#, Kotlin, Java, JS/TS, Python, Go, ...).
 *   node .kura/rules-check.mjs check      exit 1 on a NEW violation, or on a fixed one that is still in the baseline
 *   node .kura/rules-check.mjs baseline   first run: record today's violations, later: only lower or remove entries
 *   node .kura/rules-check.mjs selftest   every check rejects what it is there to catch
 * Config: .kura/rules.json. Baseline (ratchet): .kura/baseline.json, it may only shrink.
 */
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..');
const posix = (p) => String(p).replace(/\\/g, '/');
const rx = (source, flags = '') => (source ? new RegExp(source, flags) : null);

// ---- import extraction per extension (shortcut: regex, not a parser, a fully qualified name without an import is missed) ----
const IMPORTS = [
    [/\.(?:[cm]?[jt]sx?)$/, /(?:\bfrom\s*|\bimport\s*\(?\s*|\brequire\(\s*)['"]([^'"]+)['"]/g],
    [/\.cs$/, /^\s*(?:global\s+)?using\s+(?:static\s+)?(?:\w+\s*=\s*)?([\w.]+)\s*;/gm],
    [/\.(?:kts?|java|scala|groovy)$/, /^\s*import\s+(?:static\s+)?([\w.]+)/gm],
    [/\.py$/, /^\s*(?:from\s+([\w.]+)\s+import|import\s+([\w.]+))/gm],
    [/\.go$/, /^\s*(?:import\s+)?(?:[\w.]+\s+)?"([\w./-]+)"\s*$/gm]
];
export function importsOf(file, text) {
    const pattern = IMPORTS.find(([ext]) => ext.test(file))?.[1];
    if (!pattern) return [];
    return [...text.matchAll(pattern)].map(m => m[1] ?? m[2]).map(target =>
        target.startsWith('.') && !/\.py$/.test(file) ? posix(path.posix.join(path.posix.dirname(file), target)) : target);
}

// ---- the checks: each returns { key: value } of what is above the norm today ----
const lineCount = (text) => text.split(/\r?\n/).length;
const countOf = (text, pattern) => (pattern ? (text.match(new RegExp(pattern.source, 'g')) ?? []).length : 0);
const layerOf = (layers, file) => Object.entries(layers).find(([, l]) => rx(l.files).test(file))?.[0];
const importHits = (layer, target) => rx(layer.files)?.test(target) || rx(layer.imports)?.test(target);

export const CHECKS = {
    fileLines: ({ sources }, cfg) => pick(sources, (f) => { const n = lineCount(f.text); return n > cfg.max ? n : 0; }),
    statusBranches: ({ sources }, cfg) => pick(sources, (f) => countOf(f.text, rx(cfg.pattern))),
    elseIf: ({ sources }) => pick(sources, (f) => countOf(f.text, /\belse\s+if\b|\belif\b|\belse\s*->\s*if\b/)),
    dumpFolders: ({ sources }, cfg) => Object.fromEntries(sources.flatMap(f => posix(path.posix.dirname(f.file)).split('/')
        .map((seg, i, all) => (cfg.names.includes(seg.toLowerCase()) ? [all.slice(0, i + 1).join('/'), 1] : null)).filter(Boolean))),
    dependencies: ({ sources }, cfg) => Object.fromEntries(sources.flatMap(({ file, text }) => {
        const from = layerOf(cfg.layers, file);
        return importsOf(file, text).flatMap(target => cfg.rules.flatMap(rule => {
            const to = cfg.layers[rule.to];
            if (!to || !importHits(to, target) || from === rule.to) return [];
            const allowed = rule.onlyFrom ? rule.onlyFrom.includes(from) : rule.from !== from;
            return allowed ? [] : [[`${file} -> ${target} (${rule.why ?? `${from ?? 'outside'} may not use ${rule.to}`})`, 1]];
        }));
    })),
    contracts: ({ sources, tests }, cfg) => {
        const testText = tests.filter(t => rx(cfg.tests).test(t.file)).map(t => t.text).join('\n');
        return Object.fromEntries(sources.filter(f => rx(cfg.adapters).test(f.file))
            .map(f => path.posix.basename(f.file).replace(/\.[^.]+$/, ''))
            .filter(name => !new RegExp(`\\b${name}\\b`).test(testText)).map(name => [name, 1]));
    },
    complexity: ({ functions }, cfg) => pickFn(functions, fn => (fn.ccn > cfg.max ? fn.ccn : 0)),
    functionLines: ({ functions }, cfg) => pickFn(functions, fn => (fn.nloc > cfg.max ? fn.nloc : 0)),
    parameters: ({ functions }, cfg) => pickFn(functions, fn => (fn.params > cfg.max ? fn.params : 0)),
    agentsPaths: (_, cfg) => {
        const text = fs.existsSync(path.join(ROOT, cfg.file)) ? fs.readFileSync(path.join(ROOT, cfg.file), 'utf8') : '';
        return Object.fromEntries([...text.matchAll(/`([\w.-]+\/[\w./-]*[\w-]\.[a-z]{1,5})`/g)].map(m => m[1])
            .filter(p => !fs.existsSync(path.join(ROOT, p))).map(p => [p, 1]));
    }
};
function pick(files, measure) { return Object.fromEntries(files.map(f => [f.file, measure(f)]).filter(([, n]) => n > 0)); }
function pickFn(functions, measure) {
    const out = {};
    for (const fn of functions) { const n = measure(fn); if (n > 0) out[`${fn.file}::${fn.name}`] = Math.max(out[`${fn.file}::${fn.name}`] ?? 0, n); }
    return out;
}

/** lizard --csv rows: NLOC,CCN,token,PARAM,length,location,file,function,long_name,start,end (no header). */
export function parseLizard(csv) {
    return csv.split(/\r?\n/).filter(Boolean).map(line => [...line.matchAll(/"([^"]*)"|([^,]+)|(?<=,)(?=,|$)/g)].map(m => m[1] ?? m[2] ?? ''))
        .filter(cols => /^\d+$/.test(cols[0])).map(c => ({ nloc: +c[0], ccn: +c[1], params: +c[3], file: posix(c[6]).replace(/^\.\//, ''), name: c[8] || c[7] }));
}

/** The ratchet: what is worse than the baseline, and what got better but is still recorded there. */
export function compare(now, base = {}) {
    const worse = Object.entries(now).filter(([k, n]) => n > (base[k] ?? 0)).map(([k, n]) => `${k}: ${n}${k in base ? ` (baseline ${base[k]})` : ''}`);
    const stale = Object.entries(base).filter(([k, n]) => (now[k] ?? 0) < n).map(([k, n]) => `${k}: ${n} -> ${now[k] ?? 0}`);
    return { worse, stale };
}

// ---- run ----
function load() {
    const cfg = JSON.parse(fs.readFileSync(path.join(HERE, 'rules.json'), 'utf8'));
    const tracked = spawnSync('git', ['ls-files'], { cwd: ROOT, encoding: 'utf8', windowsHide: true, maxBuffer: 1 << 26 }).stdout.split(/\r?\n/).filter(Boolean);
    const read = (file) => ({ file, text: fs.readFileSync(path.join(ROOT, file), 'utf8') });
    const code = tracked.filter(f => rx(cfg.source).test(f) && !f.startsWith('.kura/') && !rx(cfg.exclude)?.test(f) && fs.existsSync(path.join(ROOT, f)));
    const isTest = (f) => rx(cfg.tests)?.test(f) ?? false;
    return { cfg, sources: code.filter(f => !isTest(f)).map(read), tests: code.filter(isTest).map(read) };
}
function lizard(cfg, files) {
    if (!['complexity', 'functionLines', 'parameters'].some(c => cfg.checks[c])) return [];
    const [cmd, ...args] = cfg.lizard ?? ['lizard'];
    const run = spawnSync(cmd, [...args, '--csv', ...cfg.roots], { cwd: ROOT, encoding: 'utf8', windowsHide: true, maxBuffer: 1 << 26 });
    if (run.status !== 0 && !run.stdout) throw new Error(`lizard did not run (${[cmd, ...args].join(' ')}): ${run.stderr || run.error}. Install it: pip install lizard`);
    const keep = new Set(files.map(f => f.file));
    return parseLizard(run.stdout).filter(fn => keep.has(fn.file));
}
function measureAll() {
    const { cfg, sources, tests } = load();
    const input = { sources, tests, functions: lizard(cfg, sources) };
    return Object.fromEntries(Object.entries(cfg.checks).filter(([, c]) => c).map(([name, c]) => [name, CHECKS[name](input, c)]));
}

const BASELINE = path.join(HERE, 'baseline.json');
const COMMANDS = {
    check: () => {
        const base = fs.existsSync(BASELINE) ? JSON.parse(fs.readFileSync(BASELINE, 'utf8')) : {};
        let red = false;
        for (const [name, now] of Object.entries(measureAll())) {
            const { worse, stale } = compare(now, base[name]);
            if (worse.length) { red = true; console.log(`rules: ${name} got worse (fix it; never raise the baseline):\n  ${worse.join('\n  ')}`); }
            if (stale.length) { red = true; console.log(`rules: ${name} got better, lower the baseline (node .kura/rules-check.mjs baseline):\n  ${stale.join('\n  ')}`); }
        }
        console.log(red ? 'rules: red' : 'rules: green');
        process.exit(red ? 1 : 0);
    },
    baseline: () => {
        const now = measureAll();
        const old = fs.existsSync(BASELINE) ? JSON.parse(fs.readFileSync(BASELINE, 'utf8')) : null;
        // After the first run the ratchet only tightens: an entry is lowered or removed, never added or raised.
        // `--add` records a check that was switched on later (it is not in the baseline yet), the others still only tighten.
        const tightened = old ? Object.fromEntries(Object.entries(old).filter(([name]) => name !== 'note').map(([name, base]) => [name, Object.fromEntries(
            Object.entries(base).map(([k, n]) => [k, Math.min(n, now[name]?.[k] ?? 0)]).filter(([, n]) => n > 0))])) : now;
        const added = old && process.argv.includes('--add') ? Object.fromEntries(Object.entries(now).filter(([name]) => !(name in old))) : {};
        const next = { ...tightened, ...added };
        fs.writeFileSync(BASELINE, `${JSON.stringify({ ...next, note: 'Ratchet: only lower or remove entries. Never add.' }, null, 2)}\n`);
        console.log(`rules: baseline ${old ? 'tightened' : 'recorded'} in .kura/baseline.json`);
    },
    selftest: () => {
        const f = (file, text) => ({ file, text });
        const sources = [
            f('src/Domain/Order.cs', 'using MyApp.Infrastructure.Db;\nif (status == "a") {} else if (x) {}'),
            f('src/Infrastructure/SqlOrderStore.cs', 'class SqlOrderStore {}'),
            f('src/utils/Format.kt', 'import com.app.Domain\nwhen (state) {}'),
            f('src/App/Composition.cs', 'using MyApp.Infrastructure.Db;')
        ];
        const input = { sources, tests: [f('tests/OrderStoreContract.cs', 'MemoryOrderStore')], functions: parseLizard('16,17,1,6,20,"x@1-20@src\\A.cs","src\\A.cs","Run","A::Run(int a)",1,20\n') };
        const layers = { domain: { files: '^src/Domain/', imports: '\\.Domain\\b' }, infra: { files: '^src/Infrastructure/', imports: '\\.Infrastructure\\b' }, composition: { files: '^src/App/' } };
        assert.deepEqual(Object.keys(CHECKS.dependencies(input, { layers, rules: [{ from: 'domain', to: 'infra' }] })).length, 1, 'MUST reject: domain uses infrastructure');
        assert.deepEqual(Object.keys(CHECKS.dependencies(input, { layers, rules: [{ to: 'infra', onlyFrom: ['composition'] }] })).length, 1, 'MUST reject: an adapter used outside the composition root (and allow the root itself)');
        assert.deepEqual(CHECKS.contracts(input, { adapters: '^src/Infrastructure/', tests: 'Contract' }), { SqlOrderStore: 1 }, 'MUST reject: an adapter without a contract test');
        assert.deepEqual(CHECKS.dumpFolders(input, { names: ['utils', 'helpers'] }), { 'src/utils': 1 }, 'MUST reject: a dumping-ground folder');
        assert.equal(CHECKS.statusBranches(input, { pattern: '\\b(?:status|state)\\s*==|\\bwhen\\s*\\(\\s*(?:status|state)\\b' })['src/Domain/Order.cs'], 1, 'MUST count a branch on a status');
        assert.equal(CHECKS.elseIf(input)['src/Domain/Order.cs'], 1, 'MUST count an else-if');
        assert.deepEqual(CHECKS.complexity(input, { max: 15 }), { 'src/A.cs::A::Run(int a)': 17 }, 'MUST reject: a function above the complexity norm');
        assert.deepEqual(CHECKS.parameters(input, { max: 5 }), { 'src/A.cs::A::Run(int a)': 6 }, 'MUST reject: too many parameters');
        assert.deepEqual(CHECKS.fileLines({ sources: [f('a.cs', 'x\n'.repeat(400))] }, { max: 300 }), { 'a.cs': 401 }, 'MUST reject: a file over the limit');
        assert.deepEqual(importsOf('src/a/b.ts', "import { x } from '../c/d.js'"), ['src/c/d.js'], 'resolves a relative import');
        assert.deepEqual(compare({ a: 3, b: 1 }, { a: 2, c: 4 }), { worse: ['a: 3 (baseline 2)', 'b: 1'], stale: ['c: 4 -> 0'] }, 'MUST reject a worse and a new entry, and report a fixed one');
        assert.deepEqual(compare({ a: 2 }, { a: 2 }), { worse: [], stale: [] }, 'an unchanged baseline is green');
        console.log('selftest ok');
    }
};

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) (COMMANDS[process.argv[2]] ?? COMMANDS.check)();
